'use strict';
const API=window.AMAL_API_BASE||'';const $=s=>document.querySelector(s);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token=sessionStorage.getItem('amal_token')||localStorage.getItem('amal_token')||'',me=null,cache={};
async function api(path,o={}){const opt={method:o.method||(o.body||o.form?'POST':'GET'),headers:{}};if(token)opt.headers.Authorization='Bearer '+token;if(o.form)opt.body=o.form;else if(o.body){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(o.body)}let r;try{r=window.AmalEngine?await window.AmalEngine.fetch(path,opt):await fetch(API+path,opt)}catch{throw Error('The Amal Connect server could not be reached. Check your connection and that the server is running.')}const ct=r.headers.get('content-type')||'';if(!ct.includes('json')&&!r.ok)throw Error(r.status===404||r.status===405?'The Amal Connect server is not connected to this site. See "Deployment" in the README.':`Server error ${r.status}`);if(!ct.includes('json'))return r;const d=await r.json();if(!r.ok){if(r.status===401&&token&&!o.quiet){token='';sessionStorage.removeItem('amal_token');localStorage.removeItem('amal_token');me=null;route()}throw Error(d.error||'Request failed')}return d}
const toast=(m,bad)=>{const d=document.createElement('div');d.className='toast '+(bad?'':'success');if(bad)d.style.background='#a43c3c';d.textContent=m;$('#toastRegion').append(d);setTimeout(()=>d.remove(),4500)};
const openModal=(t,b)=>{$('#modalTitle').textContent=t;$('#modalBody').innerHTML=b;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false')};
const closeModal=()=>{$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')};
const dt=s=>{if(!s)return'';const d=new Date(/^\d{4}-\d\d-\d\d \d\d:/.test(s)?s.replace(' ','T')+'Z':s);return isNaN(d)?String(s):d.toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'})};
const dtt=s=>{if(!s)return'';const d=new Date(/^\d{4}-\d\d-\d\d \d\d:/.test(s)?s.replace(' ','T')+'Z':s);return isNaN(d)?String(s):d.toLocaleString('en-CA',{dateStyle:'medium',timeStyle:'short'})};
function sc(s){const x=String(s).toLowerCase();if(/ready|approved|confirmed match|complete|employed|verified|connected|signed|sent|eligible on|partner|still/.test(x)&&!/not currently/.test(x))return'green';if(/pending|awaiting|scheduled|progress|review|interview|partial|verification|hold|issued|portal only|training|enrolled|session|offer|information/.test(x))return'amber';if(/not currently|mismatch|declined|error|failed|withdrawn|rejected|unsuccessful|not proceeding|left|did not|needs review/.test(x))return'red';if(/submitted|received|new/.test(x))return'blue';return'gray'}
const badge=s=>`<span class="status ${sc(s)}">${e(s)}</span>`;
const hasRole=(...r)=>me?.roles.some(x=>r.includes(x));
const canP=()=>hasRole('super_admin','programme_manager','employment_advisor'),canT=()=>hasRole('super_admin','programme_manager','training_coordinator'),canC=()=>hasRole('super_admin','programme_manager'),canA=()=>hasRole('super_admin');
const initials=n=>String(n||'?').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const kpi=(l,v,f,to)=>`<div class="card kpi ${to?'clickable':''}" ${to?`data-go="${to}" tabindex="0"`:''}><div class="kpi-top">${e(l)}</div><div class="kpi-value">${e(v)}</div><div class="kpi-foot">${e(f)}</div></div>`;
const head=(t,s='',x='')=>`<div class="card-head"><div><div class="card-title">${e(t)}</div>${s?`<div class="card-sub">${e(s)}</div>`:''}</div>${x}</div>`;
const empty=m=>`<div class="empty">${e(m)}</div>`;
const fld=(l,n,o={})=>`<div class="form-field ${o.full?'full':''}"><label for="f_${n}">${e(l)}${o.req?' *':''}</label>${o.options?`<select id="f_${n}" name="${n}" ${o.req?'required':''}>${o.options.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return`<option value="${e(v)}" ${String(o.value??'')===String(v)?'selected':''}>${e(t)}</option>`}).join('')}</select>`:o.area?`<textarea id="f_${n}" name="${n}" ${o.req?'required':''} placeholder="${e(o.ph||'')}" style="min-height:${o.h||90}px">${e(o.value??'')}</textarea>`:`<input id="f_${n}" name="${n}" type="${o.type||'text'}" ${o.req?'required':''} ${o.min?`minlength="${o.min}"`:''} value="${e(o.value??'')}" placeholder="${e(o.ph||'')}" ${o.accept?`accept="${o.accept}"`:''}>`}</div>`;
const modalBtns=(l,x='')=>`<div class="modal-actions">${x}<button type="button" class="btn btn-light" data-act="closeModal">Cancel</button><button class="btn btn-primary">${e(l)}</button></div>`;
const CV_ACCEPT='.pdf,.doc,.docx,.rtf,.txt,.png,.jpg,.jpeg';
const STAGES=['Application received','Under review','Information session','Consent pending','Consent signed','Enrolled','Training','Activation pending','Employment Ready','Employed'];
const timeline=st=>{const i=STAGES.indexOf(st);if(i<0)return`<p>${badge(st)}</p>`;return`<div class="timeline">${STAGES.map((s,n)=>`<div class="tl-step ${n<i?'done':n===i?'now':''}"><div class="tl-dot">${n<i?'✓':''}</div>${e(s)}</div>`).join('')}</div>`};
async function download(id,name){try{const r=await api('/api/files/'+id);const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=name||'file';a.click();URL.revokeObjectURL(u)}catch(x){toast(x.message,1)}}
async function exportCsv(k){try{const r=await api('/api/export/'+k);const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=`amal-${k}.csv`;a.click();URL.revokeObjectURL(u)}catch(x){toast(x.message,1)}}
// ---------- Forms and actions registry
const forms={},acts={};
document.addEventListener('submit',async ev=>{const f=ev.target.closest('form[data-form]');if(!f)return;ev.preventDefault();const b=f.querySelector('button:not([type=button])');const old=b?.innerHTML;try{if(b){b.disabled=true;b.innerHTML='<span class="spinner"></span>Working…'}const fd=new FormData(f);await forms[f.dataset.form](Object.fromEntries(fd),f,fd)}catch(x){let er=f.querySelector('.err');if(!er){er=document.createElement('div');er.className='err';er.style.margin='10px 0';f.prepend(er)}er.textContent=x.message}finally{if(b&&b.isConnected){b.disabled=false;b.innerHTML=old}}});
document.addEventListener('click',async ev=>{const g=ev.target.closest('[data-go]');if(g){location.hash=g.dataset.go;return}const a=ev.target.closest('[data-act]');if(a){ev.preventDefault();try{await acts[a.dataset.act](a.dataset,a)}catch(x){toast(x.message,1)}return}if(ev.target.id==='modalBackdrop')closeModal()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if(ev.key==='Enter'&&ev.target.matches?.('[data-go]'))location.hash=ev.target.dataset.go});
acts.closeModal=closeModal;acts.dl=d=>download(d.id,d.name);acts.csv=d=>exportCsv(d.k);
acts.logout=async()=>{await api('/api/logout',{method:'POST',quiet:true}).catch(()=>{});token='';sessionStorage.removeItem('amal_token');localStorage.removeItem('amal_token');me=null;location.hash='#/login';route()};
const setToken=(t,keep)=>{token=t;(keep?localStorage:sessionStorage).setItem('amal_token',t)};
