const logo=`<div class="auth-logo"><span><i style="background:#e8a94b"></i><i style="background:#167d8d"></i><i style="background:#e87570"></i></span>&nbsp;&nbsp;AMAL CONNECT</div>`;
const authPage=(h,w)=>{$('#root').innerHTML=`<div class="auth-wrap"><div class="auth-card ${w?'wide':''}">${logo}${h}</div></div>`};
const viewSetup=()=>authPage(`<h1>Set up Amal Connect</h1><p>Create the first Super Administrator account. You can add staff afterwards.</p><form data-form="setup" class="stack">${fld('Full name','name',{req:1})}${fld('Email','email',{req:1,type:'email'})}${fld('Password (10+ characters)','password',{req:1,type:'password',min:10})}<button class="btn btn-primary">Create account</button></form>`);
forms.setup=async d=>{setToken((await api('/api/setup',{body:d})).token);location.hash='#/';route()};
const viewLogin=()=>authPage(`<h1>Welcome back</h1><p>Sign in to continue your employment journey or manage the programme.</p><form data-form="login" class="stack">${fld('Email','email',{req:1,type:'email'})}${fld('Password','password',{req:1,type:'password'})}<label class="mini"><input type="checkbox" name="keep"> Keep me signed in on this device</label><button class="btn btn-primary">Sign in</button></form><div class="link-row"><a href="#/apply">Apply to the programme</a></div>`);
forms.login=async d=>{setToken((await api('/api/login',{body:d,quiet:true})).token,d.keep);location.hash='#/';route()};
const viewApply=()=>authPage(`<h1>Apply to the Amal Employment Network</h1><p>Tell us about yourself. You will receive a private account to follow your progress.</p><form data-form="apply" class="stack"><div class="form-grid">${fld('Full name','name',{req:1})}${fld('Email','email',{req:1,type:'email'})}${fld('Phone','phone',{type:'tel'})}${fld('City or community','city')}${fld('How did you hear about Amal?','source',{full:1})}${fld('Create a password (10+ characters)','password',{req:1,type:'password',min:10,full:1})}<div class="form-field full"><label>Your CV (optional: PDF, Word or a photo)</label><input type="file" name="cv" accept="${CV_ACCEPT}"></div></div><label class="mini"><input type="checkbox" required> I agree that Amal may use this information to review my application.</label><button class="btn btn-primary">Submit application</button></form><div class="link-row"><a href="#/login">I already have an account</a></div>`,1);
forms.apply=async(d,f,fd)=>{if(!fd.get('cv')?.size)fd.delete('cv');const r=await api('/api/apply',{form:fd,quiet:true});setToken(r.token);toast('Application received. Your reference is '+r.code);location.hash='#/';route()};
const viewInvite=t=>authPage(`<h1>Set your password</h1><p>Create a password to activate your Amal Connect account.</p><form data-form="invite" class="stack"><input type="hidden" name="token" value="${e(t)}">${fld('New password (10+ characters)','password',{req:1,type:'password',min:10})}<button class="btn btn-primary">Activate account</button></form>`);
forms.invite=async d=>{setToken((await api('/api/invite/accept',{body:d,quiet:true})).token);location.hash='#/';route()};
// ---------- Layout
const NAV=[[null,[['overview','▦','Overview']]],['PEOPLE & PROGRAMME',[['applicants','♙','Applicants'],['participants','♧','Participants'],['sessions','◷','Information Sessions'],['enrolment','▤','Consent & Enrolment'],['training','▣','Training & Activation'],['ready','✦','Employment Ready Pool']]],['TALENT INTELLIGENCE',[['jobs','⌕','Job Discovery'],['matching','◎','Job Matching'],['referrals','➜','Referrals'],['employers','▥','Employers'],['outcomes','↗','Outcomes & Retention']]],['ADMINISTRATION',[['communications','✉','Communications'],['reports','▤','Reports & Analytics'],['settings','⚙','Settings & Roles']]]];
const PNAV=[['home','▦','My Dashboard'],['application','▤','My Application'],['appointments','◷','My Appointments'],['training','▣','My Training'],['documents','▥','My Documents'],['profile','✦','My Employment Profile'],['jobs','⌕','Find Jobs'],['applications','➜','My Applications'],['messages','✉','Messages'],['account','⚙','My Account']];
function shell(items,base,page,title,sub,body,actions=''){const groups=items[0]&&Array.isArray(items[0][1])?items:[[null,items]];
 $('#root').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark" aria-hidden="true"><i class="person p1"></i><i class="person p2"></i><i class="person p3"></i></div><div><div class="brand-name">AMAL</div><div class="brand-sub">UNITE &amp; EMPOWER</div></div></div><nav aria-label="Main">${groups.map(([g,l])=>`${g?`<div class="nav-group-label">${g}</div>`:''}${l.map(([k,i,t])=>`<button class="nav-item ${k===page?'active':''}" data-go="${base}${k}"><span class="nav-icon">${i}</span> ${t}</button>`).join('')}`).join('')}</nav><div class="sidebar-bottom"><div class="profile-mini"><div class="avatar">${e(initials(me.name))}</div><div><strong>${e(me.name)}</strong><span>${e(me.staff?me.roles.map(r=>r.replace(/_/g,' ')).join(', '):'Participant')}</span></div></div></div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" data-act="menu" aria-label="Toggle navigation">☰</button><div class="breadcrumb"><span>Amal Connect</span><span class="crumb-slash">/</span><strong>${e(title)}</strong></div><div class="top-actions">${me.staff?`<form data-form="gsearch" class="global-search"><span>⌕</span><input name="q" placeholder="Search people…" aria-label="Search people"></form>`:''}<button class="portal-switch" data-act="logout">Sign out</button></div></header><section class="page-wrap"><div class="page-heading"><div><h1>${e(title)}</h1><p>${e(sub)}</p></div><div class="heading-actions">${actions}</div></div><div id="pageContent">${body}</div><footer class="footer"><span>AMAL CONNECT <b>•</b> PEOPLE. PROGRESS. OPPORTUNITY.</span></footer></section></main></div>`}
acts.menu=()=>$('#sidebar').classList.toggle('open');
forms.gsearch=async d=>{location.hash='#/participants?q='+encodeURIComponent(d.q)};
const loading=()=>{const c=$('#pageContent');if(c)c.innerHTML='<div class="empty"><span class="spinner"></span>Loading…</div>'};
const staffOpts=async()=>[['','Unassigned'],...(await api('/api/staff')).map(s=>[s.id,s.name])];
// ---------- Staff pages
const P={};const T={};
T.overview=['Employment Network Overview','Live figures from Amal Connect records.'];
P.overview=async()=>{const d=await api('/api/overview'),max=Math.max(1,...d.funnel.map(f=>f.count)),t=d.tasks;const Q=[['Applications to review',t.applications,'applicants'],['Possible duplicates',t.duplicates,'applicants?dupes=1'],['Consents awaiting signature',t.consents,'enrolment'],['Ready to enrol',t.enrol,'enrolment'],['Training completions to verify',t.training,'training'],['Activation sessions open',t.activation,'training'],['Referrals awaiting approval',t.referrals,'referrals'],['Retention check-ins due',t.retention,'outcomes']];const pm=Math.max(1,...d.places.map(x=>x.n));
 return`<div class="grid kpi-grid">${kpi('Active participants',d.kpi.participants,'All current records','#/participants')}${kpi('Employment ready',d.kpi.ready,'Passed every gate','#/ready')}${kpi('Open vacancies',d.kpi.vacancies,d.lastSync?'Last discovery '+dtt(d.lastSync):'Discovery has not run yet','#/jobs')}${kpi('Matches to review',d.kpi.matchesToReview,'Eligible or needing verification','#/matching')}</div><div class="grid overview-grid"><div class="card">${head('Participant journey','People who have reached each stage')}${d.funnel.map(f=>`<div class="funnel-row"><span>${e(f.stage)}</span><div class="funnel-track"><div class="funnel-fill" style="width:${f.count/max*100}%"></div></div><strong>${f.count}</strong></div>`).join('')}</div><div class="card">${head('Referral outcomes','Current status of all referrals')}${d.outcomes.length?d.outcomes.map(o=>`<div class="queue-item"><div class="queue-copy"><strong>${e(o.status)}</strong></div><div class="queue-number">${o.n}</div></div>`).join(''):empty('No referrals yet.')}</div></div><div class="grid lower-grid"><div class="card">${head('Staff action queue','Items that need attention')}<div class="queue-list">${Q.map(x=>`<div class="queue-item clickable" data-go="#/${x[2]}"><div class="queue-copy"><strong>${x[0]}</strong></div><div class="queue-number">${x[1]}</div></div>`).join('')}</div></div><div class="card">${head('Newfoundland and Labrador vacancies','Open jobs by location')}${d.places.length?d.places.map(x=>`<div class="bar-row"><span>${e(x.place)}</span><div class="bar-track"><div class="bar-fill" style="width:${x.n/pm*100}%"></div></div><strong>${x.n}</strong></div>`).join(''):empty('Run job discovery to populate this view.')}</div></div>`};
const peopleTable=(rows,kind)=>rows.length?`<table class="data-table"><thead><tr><th>Person</th><th>Record</th><th>Stage</th><th>CV</th><th>Assigned</th><th>Registered</th></tr></thead><tbody>${rows.map(p=>`<tr class="clickable" data-go="#/p/${p.id}"><td><div class="person-cell"><div class="mini-avatar">${e(initials(p.name))}</div><div><strong>${e(p.name)}</strong><small>${e(p.email)}</small></div></div></td><td>${e(p.code)}${p.duplicate_state==='Needs review'?' '+badge('Needs review'):''}</td><td>${badge(p.stage)}</td><td>${p.cv?'v'+p.cv:'None'}</td><td>${e(p.staff_name||'Unassigned')}</td><td>${dt(p.created)}</td></tr>`).join('')}</tbody></table>`:empty(kind==='applicants'?'No applications yet. Create one or share the public application link.':'No records match this view.');
async function peoplePage(view,qs){const u=new URLSearchParams({view});if(qs.q)u.set('q',qs.q);if(qs.stage)u.set('stage',qs.stage);if(qs.staff)u.set('staff',qs.staff);let rows=await api('/api/participants?'+u);if(qs.dupes)rows=rows.filter(r=>r.duplicate_state==='Needs review');const st=await staffOpts();return`<div class="card table-card"><form class="table-toolbar" data-form="pfilter" data-view="${view}"><div class="toolbar-left"><input class="field" name="q" value="${e(qs.q||'')}" placeholder="Name, email or ID"><select class="filter-select" name="stage"><option value="">All stages</option>${STAGES.concat(['Not proceeding','Withdrawn']).map(s=>`<option ${qs.stage===s?'selected':''}>${s}</option>`).join('')}</select><select class="filter-select" name="staff"><option value="">All staff</option>${st.slice(1).map(([i,n])=>`<option value="${i}" ${String(qs.staff)===String(i)?'selected':''}>${e(n)}</option>`).join('')}</select><button class="btn btn-light btn-small">Filter</button></div><button type="button" class="btn btn-light btn-small" data-act="csv" data-k="participants">Export CSV</button></form>${peopleTable(rows,view)}<div class="table-footer"><span>${rows.length} records</span></div></div>`}
forms.pfilter=async(d,f)=>{const u=new URLSearchParams(Object.entries(d).filter(([,v])=>v));location.hash=`#/${f.dataset.view}?${u}`};
const newBtn=canP=>canP?`<button class="btn btn-primary" data-act="newApp">＋ New application</button>`:'';
T.applicants=['Applicant management','Review applications, resolve possible duplicates and move people forward.'];P.applicants=q=>peoplePage('applicants',q);
T.participants=['Participant directory','Everyone enrolled in the programme and their current stage.'];P.participants=q=>peoplePage('participants',q);
acts.newApp=async()=>{const st=await staffOpts();openModal('Register an applicant',`<form data-form="newApp"><div class="form-grid">${fld('Full name','name',{req:1})}${fld('Email','email',{type:'email'})}${fld('Phone','phone',{type:'tel'})}${fld('City or community','city')}${fld('Assigned staff','staff_id',{options:st})}${fld('Referral source','source',{ph:'Walk-in, partner, staff referral'})}${fld('Notes','notes',{area:1,full:1})}</div>${modalBtns('Create application')}</form>`)};
forms.newApp=async d=>{const r=await api('/api/participants',{body:d});if(r.inviteLink){await route();openModal('Application created',`<div class="ok-box">${e(r.code)} created.${r.duplicate?' A possible duplicate was flagged for review.':''}</div><p class="card-sub" style="margin-top:12px">Portal invitation link for this applicant:</p><div class="ev" style="word-break:break-all">${e(r.inviteLink)}</div><div class="modal-actions"><button class="btn btn-primary" data-go="#/p/${r.id}">Open record</button></div>`)}else{closeModal();location.hash='#/p/'+r.id}};
const profileView=(cv)=>{const p=cv.profile;return`<div class="kv" style="margin-top:8px"><dt>Name</dt><dd>${e(p.name||'Not found')}</dd><dt>Contact</dt><dd>${e([p.email,p.phone,p.location].filter(Boolean).join(' · ')||'Not found')}</dd><dt>Experience</dt><dd>${p.experienceMonths?(p.experienceMonths/12).toFixed(1)+' years dated':'Not calculated'}</dd><dt>Education</dt><dd>${(p.education||[]).map(x=>e(x.detail)).join('<br>')||'Not found'}</dd><dt>Skills</dt><dd>${(p.skills||[]).map(s=>`<span class="chip">${e(s)}</span>`).join('')||'None identified'}</dd><dt>Certifications</dt><dd>${[...(p.certifications||[])].map(s=>`<span class="chip">${e(s)}</span>`).join('')||'None identified'}</dd><dt>Languages</dt><dd>${(p.languages||[]).map(e).join(', ')||'None stated'}</dd><dt>Work history</dt><dd>${(p.experience||[]).map(j=>`${e(j.title)}${j.employer?', '+e(j.employer):''} <span class="mini">(${e(j.start)} – ${e(j.end)})</span>`).join('<br>')||'None identified'}</dd></div>${p.notFound?.length?`<div class="warn" style="margin-top:10px">Not found in this CV: ${e(p.notFound.join(', '))}. Check the original.</div>`:''}`};
T.p=['Participant profile','The complete record for this person.'];
P.p=async(q,id)=>{const d=await api('/api/participants/'+id),p=d.participant;cache.person=d;const a=[];if(canP()){if(p.stage==='Application received')a.push(['Start review','review']);if(['Application received','Under review','Information session'].includes(p.stage))a.push(['Book information session','bookSession']);if(p.stage==='Consent pending')a.push(['Issue consent','issueConsent']);if(p.stage==='Consent signed')a.push(['Confirm enrolment','enrol']);if(p.stage==='Employment Ready')a.push(['Match against open jobs','matchP'])}if(canT()&&['Enrolled','Training'].includes(p.stage))a.push(['Assign training pathway','assignPath']);if(canT()&&p.stage==='Activation pending')a.push(['Schedule Activation Session','schedActivation']);
 return`<div class="card" style="margin-bottom:15px"><div class="card-head"><div><div class="card-title">${e(p.name)}</div><div class="card-sub">${e(p.code)} · ${e(p.entry==='public'?'Public application':'Registered by staff')}</div></div>${badge(p.stage)}</div>${timeline(p.stage)}<div class="actions-row">${a.map(([l,x],i)=>`<button class="btn ${i?'btn-light':'btn-primary'} btn-small" data-act="${x}" data-id="${p.id}">${l}</button>`).join('')}${canP()?`<button class="btn btn-light btn-small" data-act="editP" data-id="${p.id}">Edit details</button><button class="btn btn-light btn-small" data-act="sendMsg" data-id="${p.id}">Send message</button><button class="btn btn-light btn-small" data-act="withdraw" data-id="${p.id}">Withdraw</button>`:''}${canC()?`<button class="btn btn-light btn-small" data-act="correct" data-id="${p.id}">Administrative correction</button>`:''}${canA()?`<button class="btn btn-danger btn-small" data-act="delP" data-id="${p.id}">Delete record</button>`:''}</div>${d.duplicate&&p.duplicate_state==='Needs review'?`<div class="warn" style="margin-top:12px"><strong>Possible duplicate</strong> of ${e(d.duplicate.code)} ${e(d.duplicate.name)} (${e(d.duplicate.email)}). <button class="text-link" data-go="#/p/${d.duplicate.id}">Open</button> <button class="text-link" data-act="dupMerge" data-id="${p.id}">Merge into that record</button> <button class="text-link" data-act="dupDistinct" data-id="${p.id}">These are different people</button></div>`:''}</div><div class="two-col"><div class="stack"><div class="card">${head('Contact and preferences')}<dl class="kv"><dt>Email</dt><dd>${e(p.email||'—')}</dd><dt>Phone</dt><dd>${e(p.phone||'—')}</dd><dt>City</dt><dd>${e(p.city||'—')}</dd><dt>Advisor</dt><dd>${e(d.staff||'Unassigned')}</dd><dt>Availability</dt><dd>${e(p.availability)}</dd><dt>Job preferences</dt><dd>${e(Object.values(p.preferences).filter(Boolean).join(' · ')||'Not set')}</dd><dt>Notes</dt><dd>${e(p.notes||'—')}</dd></dl></div><div class="card">${head('CV versions','Original file, extraction and history')}${canP()?`<form data-form="pcv" data-id="${p.id}" class="toolbar-left" style="margin-bottom:10px"><input type="file" name="cv" required accept="${CV_ACCEPT}"><button class="btn btn-primary btn-small">Upload new version</button></form>`:''}${d.cvs.length?d.cvs.map((c,i)=>`<div class="req"><div class="req-top"><b>Version ${c.version}</b><span class="mini">${dtt(c.at)} · ${e(c.file_type)} · ${e(c.method)}</span></div>${c.warnings.map(w=>`<div class="warn" style="margin-top:6px">${e(w)}</div>`).join('')}${i===0?profileView(c):''}${c.document_id?`<button class="text-link" data-act="dl" data-id="${c.document_id}" data-name="cv-v${c.version}">Download original</button>`:''}</div>`).join(''):empty('No CV uploaded.')}</div><div class="card">${head('Staff notes')}${canP()?`<form data-form="note" data-id="${p.id}" class="toolbar-left" style="margin-bottom:8px"><input class="field" name="body" required placeholder="Add a note" style="flex:1"><button class="btn btn-light btn-small">Add</button></form>`:''}${d.notes.map(n=>`<div class="req"><small>${e(n.by_name||'')} · ${dtt(n.at)}</small>${e(n.body)}</div>`).join('')||empty('No notes.')}</div></div><div class="stack"><div class="card">${head('Information sessions')}${d.sessions.map(s=>`<div class="req"><div class="req-top"><b>${dtt(s.at)}</b>${badge(s.status)}</div><small>${e(s.location)} ${s.outcome?'· '+e(s.outcome):''} ${s.notes?'· '+e(s.notes):''}</small></div>`).join('')||empty('None booked.')}</div><div class="card">${head('Consent')}${d.consents.map(c=>`<div class="req"><div class="req-top"><b>${e(c.title)} v${c.version}</b>${badge(c.status)}</div><small>Issued ${dt(c.issued_at)}${c.signed_at?` · Signed ${dtt(c.signed_at)} by ${e(c.signed_name)}`:''}</small>${c.status==='Signed'&&canP()?`<button class="text-link" data-act="withdrawConsent" data-id="${c.id}">Record withdrawal</button>`:''}</div>`).join('')||empty('None issued.')}</div><div class="card">${head('Training and activation')}${d.assignments.map(a=>`<div class="req"><div class="req-top"><b>${e(a.title)}</b>${badge(a.status)}</div><small>Deadline ${e(a.deadline||'none')} · Attendance ${e(a.attendance||'—')} · Assessment ${e(a.assessment||'—')}</small></div>`).join('')||empty('No training assigned.')}${d.activations.map(a=>`<div class="req"><div class="req-top"><b>Activation Session · ${dtt(a.at)}</b>${badge(a.status)}</div></div>`).join('')}</div><div class="card">${head('Job matches','Assessed against the latest CV')}${d.matches.map(m=>`<div class="req clickable" data-go="#/matching?job=${m.job_id}"><div class="req-top"><b>${e(m.title)}</b><strong>${m.score}%</strong></div><small>${e(m.employer)} · ${e(m.eligibility)} · CV v${m.cv_version}</small></div>`).join('')||empty('No assessments yet.')}</div><div class="card">${head('Referrals and outcomes')}${d.referrals.map(r=>`<div class="req"><div class="req-top"><b>${e(r.job_title)}</b>${badge(r.status)}</div><small>${e(r.employer)} · ${dt(r.created)}</small></div>`).join('')}${d.outcomes.map(o=>`<div class="req"><div class="req-top"><b>${e(o.job_title)} at ${e(o.employer)}</b>${badge(o.status)}</div><small>Started ${e(o.start_date)}</small></div>`).join('')||(d.referrals.length?'':empty('None yet.'))}</div><div class="card">${head('Documents')}${d.documents.map(x=>`<div class="req"><div class="req-top"><b>${e(x.name)}</b><button class="text-link" data-act="dl" data-id="${x.id}" data-name="${e(x.name)}">Download</button></div><small>${e(x.kind)} · ${dt(x.at)}</small></div>`).join('')||empty('None.')}</div><div class="card">${head('Communications')}${d.messages.slice(0,10).map(m=>`<div class="req"><div class="req-top"><b>${e(m.subject)}</b>${badge(m.status||'')}</div><small>${dtt(m.at)}</small></div>`).join('')||empty('None.')}</div><div class="card">${head('Stage history')}${d.history.map(h=>`<div class="req"><div class="req-top"><b>${e(h.stage)}</b><span class="mini">${dtt(h.at)}</span></div><small>${e(h.note||'')} ${h.by_name?'· '+e(h.by_name):''}</small></div>`).join('')}</div></div></div>`};
const rr=()=>route();
const post=(u,b)=>api(u,{body:b||{},method:'POST'});
acts.review=async d=>{await post(`/api/participants/${d.id}/review`);toast('Review started');rr()};
acts.enrol=async d=>{await post(`/api/participants/${d.id}/enrol`);toast('Enrolment confirmed');rr()};
acts.matchP=async d=>{const r=await post(`/api/match/participant/${d.id}`);toast(`Assessed against ${r.assessed} open jobs`);rr()};
acts.dupMerge=async d=>{if(!confirm('Merge this record into the other one? This cannot be undone.'))return;const r=await post(`/api/participants/${d.id}/duplicate`,{action:'merge'});location.hash='#/p/'+r.mergedInto};
acts.dupDistinct=async d=>{await post(`/api/participants/${d.id}/duplicate`,{action:'distinct'});rr()};
const mform=(title,name,id,body,lbl)=>openModal(title,`<form data-form="${name}" data-id="${id}">${body}${modalBtns(lbl)}</form>`);
acts.bookSession=async d=>{const st=await staffOpts();mform('Book information session','bookSession',d.id,`<div class="form-grid">${fld('Date and time','at',{req:1,type:'datetime-local'})}${fld('Location or video link','location')}${fld('Staff member','staff_id',{options:st.slice(1)})}</div>`,'Book and notify')};
forms.bookSession=async(d,f)=>{await post('/api/sessions',{...d,participant_id:f.dataset.id});closeModal();toast('Session booked');rr()};
acts.issueConsent=async d=>{const t=(await api('/api/consent-templates')).filter(x=>x.active);if(!t.length){toast('Create a consent template first',1);location.hash='#/enrolment';return}mform('Issue consent','issueConsent',d.id,fld('Consent form','template_id',{req:1,options:t.map(x=>[x.id,`${x.title} (v${x.version})`])}),'Issue')};
forms.issueConsent=async(d,f)=>{await post('/api/consents',{...d,participant_id:f.dataset.id});closeModal();toast('Consent issued');rr()};
acts.assignPath=d=>mform('Assign required pathway','assignPath',d.id,fld('Deadline','deadline',{type:'date'}),'Assign');
forms.assignPath=async(d,f)=>{const r=await post('/api/assignments',{...d,pathway:1,participant_ids:[f.dataset.id]});closeModal();toast(`${r.created} programmes assigned`);rr()};
acts.schedActivation=d=>mform('Schedule Activation Session','schedAct',d.id,`<div class="form-grid">${fld('Date and time','at',{req:1,type:'datetime-local'})}${fld('Location','location')}</div>`,'Schedule');
forms.schedAct=async(d,f)=>{await post('/api/activations',{...d,participant_id:f.dataset.id});closeModal();toast('Scheduled');rr()};
acts.editP=async d=>{const p=cache.person.participant,st=await staffOpts(),pr=p.preferences;mform('Edit details','editP',d.id,`<div class="form-grid">${fld('Full name','name',{req:1,value:p.name})}${fld('Email','email',{type:'email',value:p.email})}${fld('Phone','phone',{value:p.phone})}${fld('City','city',{value:p.city})}${fld('Assigned staff','staff_id',{options:st,value:p.staff_id})}${fld('Availability','availability',{value:p.availability,options:['Available for opportunities','Currently interviewing or awaiting outcomes','Temporarily unavailable']})}${fld('Notes','notes',{area:1,full:1,value:p.notes})}</div>`,'Save')};
forms.editP=async(d,f)=>{await api('/api/participants/'+f.dataset.id,{method:'PATCH',body:d});closeModal();rr()};
acts.sendMsg=d=>mform('Send message','sendMsg',d.id,`${fld('Subject','subject',{req:1})}${fld('Message','body',{req:1,area:1})}`,'Send');
forms.sendMsg=async(d,f)=>{await post('/api/messages',{...d,participant_id:f.dataset.id});closeModal();toast('Message recorded');rr()};
acts.withdraw=d=>mform('End participation','withdraw',d.id,`${fld('Outcome','stage',{options:['Withdrawn','Not proceeding']})}${fld('Reason','reason',{req:1,area:1})}`,'Confirm');
forms.withdraw=async(d,f)=>{await post(`/api/participants/${f.dataset.id}/withdraw`,d);closeModal();rr()};
acts.correct=d=>mform('Administrative correction','correct',d.id,`<div class="warn">This bypasses the normal workflow and is permanently logged.</div>${fld('Set stage to','stage',{options:STAGES})}${fld('Documented reason','reason',{req:1,area:1})}`,'Apply correction');
forms.correct=async(d,f)=>{await post(`/api/participants/${f.dataset.id}/correct-stage`,d);closeModal();rr()};
acts.delP=d=>mform('Permanently delete this record','delP',d.id,`<div class="warn">This erases the person's record, CVs and documents. It cannot be undone. The audit log keeps only their reference number.</div>${fld('Reason','reason',{req:1})}${fld('Type '+cache.person.participant.code+' to confirm','confirm',{req:1})}`,'Delete permanently');
forms.delP=async(d,f)=>{await api('/api/participants/'+f.dataset.id,{method:'DELETE',body:d});closeModal();location.hash='#/participants'};
acts.withdrawConsent=d=>mform('Record consent withdrawal','wc',d.id,fld('Reason','reason',{req:1,area:1}),'Record');
forms.wc=async(d,f)=>{await post(`/api/consents/${f.dataset.id}/withdraw`,d);closeModal();rr()};
forms.pcv=async(d,f,fd)=>{const r=await api(`/api/participants/${f.dataset.id}/cv`,{form:fd});toast(`CV v${r.version} read (${r.fileType}, ${r.wordCount} words)`);rr()};
forms.note=async(d,f)=>{await post(`/api/participants/${f.dataset.id}/note`,d);rr()};
T.sessions=['Information sessions','Schedule, attend and record the outcome of each first conversation.'];
P.sessions=async()=>{const r=await api('/api/sessions');return`<div class="card table-card">${r.length?`<table class="data-table"><thead><tr><th>Person</th><th>When</th><th>Where</th><th>Staff</th><th>Status</th><th>Outcome</th><th></th></tr></thead><tbody>${r.map(s=>`<tr><td><a class="text-link" href="#/p/${s.participant_id}">${e(s.name)}</a></td><td>${dtt(s.at)}</td><td>${e(s.location)}</td><td>${e(s.staff_name||'')}</td><td>${badge(s.status)}</td><td>${e(s.outcome||'—')}</td><td>${s.status==='Scheduled'&&canP()?`<button class="btn btn-light btn-small" data-act="sessOut" data-id="${s.id}">Record outcome</button>`:''}</td></tr>`).join('')}</tbody></table>`:empty('No sessions booked. Book one from an applicant record.')}</div>`};
acts.sessOut=d=>mform('Record session outcome','sessOut',d.id,`${fld('Outcome','outcome',{req:1,options:['Proceeding to consent','Interested but needs follow-up','Not proceeding','Session rescheduled','Did not attend']})}${fld('Notes','notes',{area:1})}${fld('Follow-up date','follow_up',{type:'date'})}`,'Save outcome');
forms.sessOut=async(d,f)=>{await api('/api/sessions/'+f.dataset.id,{method:'PATCH',body:d});closeModal();rr()};
T.enrolment=['Consent & enrolment','Versioned consent forms, electronic signatures and enrolment.'];
P.enrolment=async()=>{const [t,c,w]=await Promise.all([api('/api/consent-templates'),api('/api/consents'),api('/api/participants?stage=Consent%20signed')]);return`<div class="card" style="margin-bottom:15px">${head('Ready to enrol','Consent signed')}${w.map(p=>`<div class="queue-item"><div class="queue-copy"><strong>${e(p.name)}</strong><span>${e(p.code)}</span></div>${canP()?`<button class="btn btn-primary btn-small" data-act="enrol" data-id="${p.id}">Confirm enrolment</button>`:''}</div>`).join('')||empty('Nobody is waiting for enrolment.')}</div><div class="two-col"><div class="card">${head('Consent records')}${c.map(x=>`<div class="req clickable" data-go="#/p/${x.participant_id}"><div class="req-top"><b>${e(x.name)}</b>${badge(x.status)}</div><small>${e(x.title)} v${x.version} · Issued ${dt(x.issued_at)}${x.signed_at?` · Signed ${dtt(x.signed_at)}`:''}</small></div>`).join('')||empty('No consent forms issued.')}</div><div class="card">${head('Consent templates','Saving a change creates a new version',canC()?`<button class="btn btn-primary btn-small" data-act="newTemplate">＋ New template</button>`:'')}${t.map(x=>`<div class="req"><div class="req-top"><b>${e(x.title)} v${x.version}</b>${badge(x.active?'Active':'Superseded')}</div><small>${e(x.body.slice(0,140))}…</small>${x.active&&canC()?`<button class="text-link" data-act="newTemplate" data-id="${x.id}">New version</button>`:''}</div>`).join('')||empty('Create the consent form Amal has approved before issuing it to participants.')}</div></div>`};
acts.newTemplate=async d=>{let x={};if(d.id)x=(await api('/api/consent-templates')).find(t=>t.id==d.id);openModal('Consent template',`<form data-form="tpl">${fld('Title','title',{req:1,value:x.title})}${fld('Consent text','body',{req:1,area:1,h:240,value:x.body})}${modalBtns('Save version')}</form>`)};
forms.tpl=async d=>{await post('/api/consent-templates',d);closeModal();rr()};
T.training=['Training & activation','Configure programmes, assign them and verify completion.'];
P.training=async()=>{const [pr,a,ac]=await Promise.all([api('/api/programmes'),api('/api/assignments'),api('/api/activations')]);return`<div class="card" style="margin-bottom:15px">${head('Training library','Programmes marked required form the mandatory pathway',canT()?`<button class="btn btn-primary btn-small" data-act="newProg">＋ New programme</button>`:'')}<div class="grid section-grid">${pr.map(x=>{const pct=x.assigned?Math.round(x.verified/x.assigned*100):0;return`<div class="card" style="box-shadow:none;border:1px solid var(--line)"><div class="eyebrow">${x.required?'REQUIRED':'OPTIONAL'}</div><div class="card-title">${e(x.title)}</div><p class="card-sub">${e(x.description)}</p><div class="progress-track"><span style="width:${pct}%"></span></div><p class="mini">${x.verified} of ${x.assigned} verified</p>${x.materials.map(m=>`<button class="text-link" data-act="dl" data-id="${m.id}" data-name="${e(m.name)}">${e(m.name)}</button><br>`).join('')}${canT()?`<button class="text-link" data-act="editProg" data-id="${x.id}">Edit</button> · <button class="text-link" data-act="addMat" data-id="${x.id}">Add material</button>`:''}</div>`}).join('')}</div></div><div class="card" style="margin-bottom:15px">${head('Participant assignments','Completion and verification are separate actions')}${a.length?`<table class="data-table"><thead><tr><th>Participant</th><th>Programme</th><th>Deadline</th><th>Attendance</th><th>Assessment</th><th>Status</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td><a class="text-link" href="#/p/${x.participant_id}">${e(x.name)}</a></td><td>${e(x.title)}</td><td>${e(x.deadline||'—')}</td><td>${e(x.attendance||'—')}</td><td>${e(x.assessment||'—')}</td><td>${badge(x.status)}</td><td>${canT()&&x.status!=='Verified'?`<button class="btn btn-light btn-small" data-act="editAssign" data-id="${x.id}" data-a="${e(x.attendance||'')}" data-s="${e(x.assessment||'')}" data-st="${e(x.status)}">Update</button>${x.status==='Completed'?` <button class="btn btn-primary btn-small" data-act="verify" data-id="${x.id}">Verify</button>`:''}`:''}</td></tr>`).join('')}</tbody></table>`:empty('No assignments yet. Assign the pathway from an enrolled participant record.')}</div><div class="card">${head('Activation Sessions','Unlocked once all required training is verified')}${ac.eligible.map(p=>`<div class="queue-item"><div class="queue-copy"><strong>${e(p.name)}</strong><span>All required training verified</span></div>${canT()?`<button class="btn btn-primary btn-small" data-act="schedActivation" data-id="${p.id}">Schedule</button>`:''}</div>`).join('')}${ac.rows.map(x=>`<div class="queue-item"><div class="queue-copy"><strong>${e(x.name)}</strong><span>${dtt(x.at)} · ${e(x.location)} ${x.assessment?'· '+e(x.attendance)+' · '+e(x.assessment):''}</span></div>${badge(x.status)}${canT()&&x.status==='Scheduled'?`<button class="btn btn-light btn-small" data-act="recAct" data-id="${x.id}">Record</button>`:''}${canT()&&x.status==='Completed'?`<button class="btn btn-primary btn-small" data-act="appAct" data-id="${x.id}">Approve</button>`:''}</div>`).join('')||(ac.eligible.length?'':empty('No Activation Sessions yet.'))}</div>`};
acts.newProg=()=>mform('New programme','prog','',progBody({}),'Create');
const progBody=x=>`${fld('Title','title',{req:1,value:x.title})}${fld('Description','description',{area:1,value:x.description})}${fld('Objectives','objectives',{area:1,value:x.objectives})}${fld('Completion requirements','completion',{area:1,value:x.completion})}${fld('Required for Employment Ready?','required',{options:[['1','Yes'],['0','No']],value:x.required??0})}`;
acts.editProg=async d=>{const x=(await api('/api/programmes')).find(p=>p.id==d.id);mform('Edit programme','prog',d.id,progBody(x),'Save')};
forms.prog=async(d,f)=>{d.required=d.required==='1';if(f.dataset.id)await api('/api/programmes/'+f.dataset.id,{method:'PATCH',body:d});else await post('/api/programmes',d);closeModal();rr()};
acts.addMat=d=>mform('Add learning material','mat',d.id,`<div class="form-field"><label>File</label><input type="file" name="file" required></div>`,'Upload');
forms.mat=async(d,f,fd)=>{await api(`/api/programmes/${f.dataset.id}/materials`,{form:fd});closeModal();rr()};
acts.editAssign=d=>mform('Update assignment','assign',d.id,`${fld('Status','status',{options:['Not started','In progress','Completed'],value:d.st==='Verified'?'Completed':d.st})}${fld('Attendance','attendance',{options:['','Attended','Partially attended','Did not attend'],value:d.a})}${fld('Assessment outcome','assessment',{options:['','Passed','Needs retake','Failed'],value:d.s})}${fld('Evidence notes','evidence',{area:1})}`,'Save');
forms.assign=async(d,f)=>{await api('/api/assignments/'+f.dataset.id,{method:'PATCH',body:d});closeModal();rr()};
acts.verify=async d=>{await post(`/api/assignments/${d.id}/verify`);toast('Completion verified');rr()};
acts.recAct=d=>mform('Record Activation Session','recAct',d.id,`${fld('Attendance','attendance',{req:1,options:['Attended','Did not attend']})}${fld('Assessment','assessment',{req:1,options:['Passed','Needs follow-up','Not passed']})}${fld('Notes','notes',{area:1})}`,'Save');
forms.recAct=async(d,f)=>{await api('/api/activations/'+f.dataset.id,{method:'PATCH',body:{...d,action:'record'}});closeModal();rr()};
acts.appAct=async d=>{await api('/api/activations/'+d.id,{method:'PATCH',body:{action:'approve'}});toast('Participant is now Employment Ready');rr()};
T.ready=['Employment Ready Pool','People who passed every gate and can be matched to jobs.'];
P.ready=async q=>{let r=await api('/api/participants?view=ready'+(q.q?'&q='+encodeURIComponent(q.q):''));if(q.availability)r=r.filter(x=>x.availability===q.availability);return`<div class="card table-card"><form class="table-toolbar" data-form="pfilterReady"><div class="toolbar-left"><input class="field" name="q" value="${e(q.q||'')}" placeholder="Search"><select class="filter-select" name="availability"><option value="">Any availability</option>${['Available for opportunities','Currently interviewing or awaiting outcomes','Temporarily unavailable'].map(a=>`<option ${q.availability===a?'selected':''}>${a}</option>`).join('')}</select><button class="btn btn-light btn-small">Filter</button></div></form>${r.length?`<table class="data-table"><thead><tr><th>Person</th><th>Availability</th><th>Experience</th><th>Education</th><th>Top skills</th><th>Last CV</th><th>Active referrals</th></tr></thead><tbody>${r.map(p=>`<tr class="clickable" data-go="#/p/${p.id}"><td><strong>${e(p.name)}</strong><small style="display:block">${e(p.city)}</small></td><td>${badge(p.availability)}</td><td>${p.cvProfile?(p.cvProfile.months/12).toFixed(1)+' yrs':'—'}</td><td>${e(p.cvProfile?.education||'—')}</td><td>${(p.cvProfile?.skills||[]).slice(0,4).map(s=>`<span class="chip">${e(s)}</span>`).join('')}</td><td>${dt(p.cvProfile?.at)}</td><td>${p.activeReferrals}</td></tr>`).join('')}</tbody></table>`:empty('Nobody is Employment Ready yet. People appear here after Activation approval.')}</div>`};
forms.pfilterReady=async d=>{location.hash='#/ready?'+new URLSearchParams(Object.entries(d).filter(([,v])=>v))};
// ---------- Jobs
const jobCard=j=>`<div class="job-card"><div class="job-top"><div><h3>${e(j.title)}</h3><p>${e(j.employer||'Employer not stated')} · ${e(j.location||'Location not stated')}</p></div><div>${j.topScore!=null?`<div class="match-score">${j.topScore}%<div class="card-sub">best match</div></div>`:badge(j.status)}</div></div><div class="job-meta"><span>${e(j.type||'Type not stated')}</span><span>Source: ${e(j.source_name)}</span>${/adzuna/i.test(j.url||'')?'<span class="adz"><a href="https://www.adzuna.ca" target="_blank" rel="noopener">Jobs</a> by <a href="https://www.adzuna.ca" target="_blank" rel="noopener">Adzuna</a></span>':''}${j.posted?`<span>Posted ${dt(j.posted)}</span>`:''}${j.closing?`<span>Closes ${dt(j.closing)}</span>`:''}<span>${j.requirementCount} requirements read</span>${j.truncated?'<span>Excerpt only</span>':''}</div><div class="actions-row" style="margin-top:8px">${j.url?`<a class="text-link" target="_blank" rel="noopener" href="${e(j.url)}">Original posting ↗</a>`:''}<button class="text-link" data-go="#/matching?job=${j.id}">Match candidates →</button>${canP()?`<button class="text-link" data-act="editJob" data-id="${j.id}">Add full advert / edit</button>`:''}</div></div>`;
T.jobs=['Job discovery centre','Search permitted sources and manage the central job bank.'];
P.jobs=async q=>{const [src,jobs]=await Promise.all([api('/api/sources'),api('/api/jobs?'+new URLSearchParams({query:q.query||'',location:q.location||'',type:q.type||''}))]);cache.lastJobs=jobs;const fd=window.AmalEngine?await window.AmalEngine.feed():null;const liveCount=fd?fd.sources.filter(s=>['adzuna','jooble'].includes(s.kind)&&s.ok).length:src.rows.filter(s=>['adzuna','jooble'].includes(s.kind)&&s.enabled).length;return`<div class="card" style="margin-bottom:15px">${head('Search vacancies','Searches every connected source, saves new jobs to the bank, and removes duplicates')}<form data-form="jobSearch" class="toolbar-left" style="margin-bottom:12px"><input class="field" name="query" value="${e(q.query||'')}" placeholder="Job title, skill or employer" style="min-width:230px"><input class="field" name="location" value="${e(q.location||'')}" placeholder="Community (blank = all NL)"><select class="filter-select" name="type"><option value="">Any work type</option>${['Full-time','Part-time','Contract'].map(t=>`<option ${q.type===t?'selected':''}>${t}</option>`).join('')}</select><button class="btn btn-primary">Search</button>${canP()?`<button type="button" class="btn btn-light" data-act="addJob">＋ Add a vacancy</button>${window.AmalEngine?'':`<button type="button" class="btn btn-light" data-act="importUrl">Import from link</button>`}`:''}</form>${liveCount?'':`<div class="warn">No live API is connected yet, so results come from the job bank and the monthly Job Bank open data. Add a free Adzuna key for same-day vacancies (see README).</div>`}<div id="searchNote"></div><div id="jobList">${jobs.length?jobs.map(jobCard).join(''):empty('No vacancies in the job bank match. Run discovery below or broaden the search.')}</div></div><div class="card" style="margin-bottom:15px">${head('Source connections',src.lastSync?`${window.AmalEngine?'GitHub collects jobs every 6 hours':`Automatic discovery every ${src.intervalHours} hours`} · Last refreshed ${dtt(src.lastSync)}`:`Automatic discovery every ${src.intervalHours} hours`,canP()?`<div class="actions-row"><button class="btn btn-light btn-small" data-act="syncAll">Run discovery now</button>${canC()&&!window.AmalEngine?`<button class="btn btn-primary btn-small" data-act="addSource">＋ Connect source</button>`:''}</div>`:'')}${src.rows.map(s=>`<div class="queue-item"><div class="queue-copy"><strong>${e(s.name)}</strong><span>${e(s.kindLabel)}${s.last_ok?` · ${s.last_count} retrieved ${dtt(s.last_ok)}`:''} · ${s.jobs} open in bank${s.permission?` · Basis: ${e(s.permission)}`:''}</span>${s.last_error?`<span style="color:#a43c3c">${e(s.last_error)}</span>`:''}</div>${badge(s.enabled?s.status:'Disabled')}${canP()?`<button class="text-link" data-act="syncOne" data-id="${s.id}">Test / sync</button>`:''}${canC()&&!window.AmalEngine?`<button class="text-link" data-act="toggleSrc" data-id="${s.id}" data-on="${s.enabled?0:1}">${s.enabled?'Disable':'Enable'}</button> <button class="text-link" data-act="delSrc" data-id="${s.id}">Remove</button>`:''}</div>`).join('')}</div>${window.AmalEngine?await feedStatus():''}<div class="card">${head('Search Job Bank directly','Official Government of Canada widget. Its results stay inside the widget; add a posting above to match it.')}<details><summary>Open Job Bank search</summary><iframe class="embed" title="Job Bank search" src="https://www.jobbank.gc.ca/widgetjs/" loading="lazy"></iframe></details><p class="mini" style="margin-top:10px">Other official searches: <a class="text-link" target="_blank" rel="noopener" href="https://www.hiring.gov.nl.ca/Competitions/Public">Government of NL competitions ↗</a> · <a class="text-link" target="_blank" rel="noopener" href="https://www.jobbank.gc.ca/jobsearch/jobsearch?locationstring=Newfoundland+and+Labrador">Job Bank in NL ↗</a></p><p class="mini">${liveAttribution(src)}</p></div>`};
async function feedStatus(){const f=await window.AmalEngine.feed();const repo=window.AmalEngine.repoUrl;return`<div class="card" style="margin-bottom:15px">${head('Sources in the automatic feed',f.generated?`Collected ${dtt(f.generated)} · ${f.jobs.length} Newfoundland and Labrador vacancies`:'The GitHub job has not produced a feed yet',repo?`<a class="btn btn-light btn-small" target="_blank" rel="noopener" href="${repo}/actions">Run or check the job ↗</a>`:'')}${f.sources.map(s=>`<div class="queue-item"><div class="queue-copy"><strong>${e(s.name)}</strong><span>${s.ok?`${s.retrieved} retrieved, ${s.inNL} in NL`:e(s.error||'')}</span></div>${badge(s.ok?'Connected':s.skipped?'Needs key':'Error')}</div>`).join('')||empty('Sources appear here after the first GitHub job run.')}</div>`}
const liveAttribution=s=>false?'<a href="https://www.adzuna.ca" target="_blank" rel="noopener">Jobs</a> by <a href="https://www.adzuna.ca" target="_blank" rel="noopener">Adzuna</a>':'';
forms.jobSearch=async d=>{const r=await post('/api/jobs/live-search',d);const n=$('#searchNote'),err=r.summary.filter(s=>s.error),done=r.summary.filter(s=>!s.error);n.innerHTML=`${done.length?`<div class="ok-box" style="margin-bottom:10px">Checked ${done.map(s=>`${e(s.source)}: ${s.retrieved} retrieved, ${s.added} new`).join(' · ')}</div>`:''}${err.map(s=>`<div class="err" style="margin-bottom:8px">${e(s.source)}: ${e(s.error)}</div>`).join('')}`;$('#jobList').innerHTML=r.jobs.length?r.jobs.map(j=>jobCard({...j,topScore:null})).join(''):empty('No vacancies matched this search in Newfoundland and Labrador.');toast(`${r.jobs.length} ${r.jobs.length===1?'vacancy':'vacancies'} found`)};
acts.addJob=()=>mform('Add a vacancy','addJob','',jobFields({}),'Save vacancy');
const jobFields=j=>`<div class="form-grid">${fld('Job title','title',{req:1,value:j.title})}${fld('Employer','employer',{value:j.employer})}${fld('Location','location',{value:j.location,ph:"St. John's, NL"})}${fld('Work type','type',{value:j.type})}${fld('Closing date','closing',{type:'date',value:(j.closing||'').slice(0,10)})}${fld('Link to original posting','url',{type:'url',value:j.url})}${fld('Full job advert','description',{area:1,h:190,full:1,value:j.description,ph:'Paste the complete advert, including requirements'})}</div>`;
forms.addJob=async d=>{const r=await post('/api/jobs',d);closeModal();toast('Vacancy saved');location.hash='#/matching?job='+r.id;};
acts.editJob=async d=>{const j=await api('/api/jobs/'+d.id);mform('Edit vacancy','editJob',d.id,`${jobFields(j)}${fld('Status','status',{options:['Open','Closed'],value:j.status})}`,'Save')};
forms.editJob=async(d,f)=>{await api('/api/jobs/'+f.dataset.id,{method:'PATCH',body:d});closeModal();rr()};
acts.importUrl=()=>mform('Import from an employer link','imp','',`<p class="card-sub">Reads the structured job data an employer publishes on its own posting page. Sites that block automated reading are respected.</p>${fld('Posting address','url',{req:1,type:'url'})}`,'Import');
forms.imp=async d=>{const r=await post('/api/jobs/import-url',d);closeModal();toast('Imported: '+r.job.title);rr()};
acts.syncAll=async()=>{toast('Discovery started. This can take a minute.');const r=await post('/api/sources/sync-all');const er=r.filter(s=>s.error);toast(`${r.length-er.length} sources updated${er.length?`, ${er.length} failed`:''}`,er.length>0);rr()};
acts.syncOne=async d=>{toast('Contacting source…');try{const r=await post(`/api/sources/${d.id}/sync`);toast(`${r.retrieved} retrieved, ${r.inNL} in NL, ${r.added} new`)}catch(x){toast(x.message,1)}rr()};
acts.toggleSrc=async d=>{await api('/api/sources/'+d.id,{method:'PATCH',body:{enabled:d.on==='1'}});rr()};
acts.delSrc=async d=>{if(confirm('Remove this source? Jobs already imported stay in the bank.')){await api('/api/sources/'+d.id,{method:'DELETE'});rr()}};
const SRC_HELP={adzuna:'Free key at developer.adzuna.com. Shows "Jobs by Adzuna" as its terms require. Excerpts only.',jooble:'Request a key at jooble.org/api/about. Excerpts only.',greenhouse:'For an employer using Greenhouse. The board name is the last part of boards.greenhouse.io/name.',lever:'For an employer using Lever. The board name is the last part of jobs.lever.co/name.',ashby:'For an employer using Ashby. The board name is the last part of jobs.ashbyhq.com/name.',smartrecruiters:'For an employer using SmartRecruiters. The board name is the company ID in its careers link.',rss:'Use a feed the provider publishes or has given Amal, including the Job Bank XML feed once approved.',json:'Use a JSON job feed the provider publishes or has given Amal.',jobbank_open:'Government open data, updated monthly. Added by default.'};
const NEED={appId:'App ID',appKey:'App key',apiKey:'API key',board:'Board name',url:'Feed address'};
acts.addSource=async()=>{const {kinds}=await api('/api/sources');cache.kinds=kinds;openModal('Connect a job source',`<form data-form="addSrc">${fld('Source type','kind',{req:1,options:kinds.map(k=>[k.kind,k.label])})}<div id="srcFields"></div>${fld('Display name','name',{req:1})}${fld('Permission or terms basis','permission',{ph:'Published API terms, employer agreement, licence'})}${modalBtns('Save and connect')}</form>`);const s=$('#f_kind');const up=()=>{const k=kinds.find(x=>x.kind===s.value);$('#srcFields').innerHTML=`<p class="mini" style="margin:8px 0">${e(SRC_HELP[k.kind]||'')}</p>`+k.needs.map(n=>fld(NEED[n],'c_'+n,{req:1,type:n.includes('Key')?'password':'text'})).join('')};s.onchange=up;up()};
forms.addSrc=async d=>{const config={};for(const k in d)if(k.startsWith('c_'))config[k.slice(2)]=d[k];const {id}=await post('/api/sources',{name:d.name,kind:d.kind,permission:d.permission,config});closeModal();try{const r=await post(`/api/sources/${id}/sync`);toast(`Connected: ${r.retrieved} retrieved, ${r.added} new`)}catch(x){toast('Saved, but the test failed: '+x.message,1)}rr()};
// ---------- Matching
const assessmentView=(m,matchId)=>{const groups={mandatory:[],preferred:[]};m.items.forEach(i=>groups[i.importance].push(i));const row=i=>`<div class="req"><div class="req-top"><b>${e(i.text)}</b>${badge(i.status)}</div><small>${e(i.category)}${i.inferred?' · importance inferred':''} · Confidence ${e(i.confidence)}. ${e(i.reason)}</small>${i.evidence?.map(v=>`<div class="ev">${e(v.text)}<div class="mini">${v.page?`Page ${v.page}, `:''}${e(v.section)}</div></div>`).join('')||''}${matchId&&canP()?`<form data-form="ovr" data-m="${matchId}" data-r="${e(i.id)}" class="toolbar-left" style="margin-top:6px"><select class="filter-select" name="status">${['Confirmed match','Partial match','Not evidenced','Confirmed mismatch','Requires human verification'].map(s=>`<option ${s===i.status?'selected':''}>${s}</option>`).join('')}</select><input class="field" name="note" placeholder="Verification note"><button class="btn btn-light btn-small">Record review</button></form>`:''}</div>`;return`<div class="two-col" style="margin-bottom:10px"><div><div class="score-big">${m.score}%</div><div class="mini">Suitability indicator, not a hiring decision</div><div style="margin-top:8px">${badge(m.eligibility)}</div></div><div>${Object.entries(m.breakdown).map(([k,v])=>`<div class="bar-row" style="grid-template-columns:100px 1fr 34px"><span>${e(k)}</span><div class="bar-track"><div class="bar-fill" style="width:${v}%"></div></div><strong>${v}</strong></div>`).join('')}<div class="mini">Evidence confidence ${m.evidenceConfidence}%</div></div></div><div class="ev" style="margin-bottom:10px">${e(m.explanation)}</div>${groups.mandatory.length?`<div class="tag" style="margin-top:12px">Mandatory (${m.mandatoryConfirmed} of ${m.mandatoryTotal} confirmed)</div>${groups.mandatory.map(row).join('')}`:''}${groups.preferred.length?`<div class="tag" style="margin-top:12px">Preferred</div>${groups.preferred.map(row).join('')}`:''}`};
T.matching=['Job matching','Explainable requirement-by-requirement comparison. It supports staff decisions and never makes them.'];
P.matching=async q=>{const jobs=await api('/api/jobs?limit=500');let right='';if(q.job){const job=await api('/api/jobs/'+q.job),ms=await api('/api/match/job/'+q.job);cache.matches=ms;cache.jobNow=job;right=`<div class="card">${head(job.title,`${job.employer||'Employer not stated'} · ${job.location||''} · ${job.source_name}`,canP()?`<button class="btn btn-light btn-small" data-act="runPool" data-id="${job.id}">Re-run against pool</button>`:'')}${job.truncated?'<div class="warn">This source provides only an excerpt. Use "Add full advert" in Job Discovery for a complete assessment.</div>':''}${ms.length?ms.map((m,i)=>`<div class="match-row clickable" data-act="showM" data-i="${i}"><div><strong>${i+1}. ${e(m.name)}</strong><p>${e(m.eligibility)} · CV v${m.cv_version} · confidence ${m.confidence}%</p></div><div class="match-score">${m.score}%</div></div>`).join(''):empty('No Employment Ready participant with a CV has been assessed for this job.')}<div id="mDetail" style="margin-top:14px"></div></div>`}return`<div class="banner"><strong>Matching rules:</strong> missing CV evidence is "Not evidenced", not proof of absence. A high score cannot override an unmet mandatory requirement. Every referral needs staff approval.</div><div class="card" style="margin-bottom:15px">${head('Upload a CV and find matching jobs','PDF, scanned PDF, DOCX, DOC or RTF. The CV is read, assessed against every open job and discarded unless saved to a participant.')}<form data-form="cvMatch"><div class="drop"><strong>Choose a CV</strong><input type="file" name="cv" required accept="${CV_ACCEPT}"><label class="mini"><input type="checkbox" name="live" value="1" checked> Also search live sources using this CV</label></div><button class="btn btn-primary" style="margin-top:10px">Read CV and find jobs</button></form><div id="cvResult" style="margin-top:14px"></div></div><div class="grid split-grid"><div class="card">${head('Assess a vacancy against the pool','Ready participants, ranked')}<select class="filter-select" style="width:100%" id="jobPick" onchange="location.hash='#/matching?job='+this.value"><option value="">Select a vacancy</option>${jobs.map(j=>`<option value="${j.id}" ${q.job==j.id?'selected':''}>${e(j.title)} · ${e(j.employer||'')}</option>`).join('')}</select></div>${right||`<div class="card">${empty('Select a vacancy to see ranked candidates.')}</div>`}</div>`};
forms.cvMatch=async(d,f,fd)=>{const box=$('#cvResult');box.innerHTML='<div class="empty"><span class="spinner"></span>Reading the CV and assessing jobs. Scanned files can take a little longer.</div>';let r;try{r=await api('/api/match/cv',{form:fd})}catch(x){box.innerHTML=`<div class="err">${e(x.message)}</div>`;return}cache.cv=r;box.innerHTML=`<div class="ok-box">Read ${e(r.fileName)}: ${r.fileType}, ${r.wordCount} words, ${r.pageCount} page(s), by ${e(r.method)}.</div>${r.warnings.map(w=>`<div class="warn" style="margin-top:8px">${e(w)}</div>`).join('')}${(r.live||[]).map(s=>s.error?`<div class="err" style="margin-top:8px">${e(s.source)}: ${e(s.error)}</div>`:`<div class="mini" style="margin-top:6px">${e(s.source)}: ${s.retrieved} retrieved, ${s.added} new</div>`).join('')}<div class="two-col" style="margin-top:12px"><div class="card" style="box-shadow:none;border:1px solid var(--line)">${head('Extracted from the CV')}${profileView({profile:r.profile})}<details style="margin-top:10px"><summary>Full extracted text</summary><pre class="cvtext">${e(r.text)}</pre></details></div><div class="card" style="box-shadow:none;border:1px solid var(--line)">${head(`Best matches from ${r.jobsAssessed} open jobs`)}${r.ranked.length?r.ranked.slice(0,25).map((m,i)=>`<div class="match-row clickable" data-act="showCvJob" data-i="${i}"><div><strong>${e(m.job.title)}</strong><p>${e([m.job.employer,m.job.location,m.eligibility].filter(Boolean).join(' · '))}</p></div><div class="match-score">${m.score}%</div></div>`).join(''):empty('There are no open jobs to assess. Run discovery or add a vacancy.')}</div></div>`};
acts.showCvJob=d=>{const m=cache.cv.ranked[d.i];openModal(m.job.title,`${m.job.url?`<a class="text-link" target="_blank" rel="noopener" href="${e(m.job.url)}">Original posting ↗</a>`:''}${assessmentView(m)}`)};
acts.runPool=async d=>{const r=await post('/api/match/job/'+d.id);toast(`${r.assessed} of ${r.pool} assessed`);rr()};
const showDetail=m=>{$('#mDetail').innerHTML=`<div class="card-title">${e(m.name)} · CV v${m.cv_version}</div>${m.previousReferrals?`<div class="warn" style="margin-top:8px">${m.previousReferrals} previous referral(s) to this employer or vacancy.</div>`:''}${assessmentView(m.result,m.id)}<div class="actions-row" style="margin-top:12px"><button class="btn btn-light btn-small" data-act="dl" data-id="${m.document_id}" data-name="cv-${e(m.code)}">Open CV</button>${canP()&&!m.hasReferral?`<button class="btn btn-primary btn-small" data-act="toReferral" data-id="${m.id}" ${m.eligibility==='Not currently eligible'?'disabled':''}>Send to referral review</button>`:''}${m.hasReferral?badge('Referral exists'):''}</div>`};
acts.showM=d=>showDetail(cache.matches[d.i]);
forms.ovr=async(d,f)=>{const r=await post('/api/match/review',{...d,match_id:f.dataset.m,requirement_id:f.dataset.r});const i=cache.matches.findIndex(x=>x.id==f.dataset.m);cache.matches[i]={...cache.matches[i],...r};showDetail(cache.matches[i]);toast('Review recorded')};
acts.toReferral=async d=>{await post('/api/referrals',{match_id:d.id});toast('Sent to Referral Approval Centre');location.hash='#/referrals'};
T.referrals=['Referral approval centre','No participant is referred to an employer without staff approval.'];
const FLOW=['Application submitted','Interview','Offer received','Employed','Unsuccessful application','Withdrawn','Employer rejection','Participant declined'];
P.referrals=async()=>{const r=await api('/api/referrals');cache.refs=r;const open=['Under Amal review','More information requested','On hold'];const a=r.filter(x=>open.includes(x.status)),b=r.filter(x=>!open.includes(x.status));return`<div class="card" style="margin-bottom:15px">${head('Awaiting decision')}${a.map(x=>`<div class="queue-item"><div class="queue-copy"><strong>${e(x.name)} → ${e(x.job_title)}</strong><span>${e(x.employer)} · ${x.score??'—'}% · ${e(x.eligibility||'')} · CV v${x.cv_version??'—'}${x.previous?` · ${x.previous} previous referral(s)`:''}</span></div>${badge(x.status)}${canP()?`<button class="btn btn-primary btn-small" data-act="decide" data-id="${x.id}">Review</button>`:''}</div>`).join('')||empty('Nothing is waiting for approval.')}</div><div class="card table-card">${head('Referral tracking')}${b.length?`<table class="data-table"><thead><tr><th>Participant</th><th>Vacancy</th><th>Status</th><th>Decided</th><th></th></tr></thead><tbody>${b.map(x=>`<tr><td><a class="text-link" href="#/p/${x.participant_id}">${e(x.name)}</a></td><td>${e(x.job_title)}<small style="display:block">${e(x.employer)}</small></td><td>${badge(x.status)}</td><td>${dt(x.decided_at)}</td><td>${canP()&&x.status!=='Declined'&&x.status!=='Employed'?`<button class="btn btn-light btn-small" data-act="track" data-id="${x.id}">Update</button>`:''}</td></tr>`).join('')}</tbody></table>`:empty('No decided referrals yet.')}</div>`};
acts.decide=d=>{const r=cache.refs.find(x=>x.id==d.id);openModal('Review referral',`<div class="kv"><dt>Participant</dt><dd>${e(r.name)} (${e(r.code)})</dd><dt>Vacancy</dt><dd>${e(r.job_title)}, ${e(r.employer)}</dd><dt>CV used</dt><dd>${r.document_id?`<button class="text-link" data-act="dl" data-id="${r.document_id}" data-name="cv">Version ${r.cv_version}</button>`:'—'}</dd></div>${r.result?assessmentView(r.result):''}<form data-form="decide" data-id="${r.id}" style="margin-top:12px">${fld('Decision','action',{req:1,options:[['approve','Approve referral'],['info','Request more information'],['hold','Hold for further review'],['decline','Decline']]})}${fld('Note or next steps for the participant','note',{area:1})}${r.eligibility==='Verification required'?`<label class="mini"><input type="checkbox" name="acknowledge"> I reviewed the unverified mandatory requirements</label>`:''}${modalBtns('Record decision')}</form>`)};
forms.decide=async(d,f)=>{await post(`/api/referrals/${f.dataset.id}/decide`,d);closeModal();toast('Decision recorded');rr()};
acts.track=d=>mform('Update referral','track',d.id,`${fld('Status','status',{req:1,options:FLOW})}${fld('Start date (if employed)','start_date',{type:'date'})}${fld('Employment type','employment_type',{options:['','Full-time','Part-time','Contract','Seasonal']})}`,'Save');
forms.track=async(d,f)=>{await api('/api/referrals/'+f.dataset.id,{method:'PATCH',body:d});closeModal();rr()};
T.employers=['Employer directory','Contacts, vacancies and referral history.'];
P.employers=async()=>{const r=await api('/api/employers');cache.emps=r;return`<div class="card">${head('Employers',`${r.length} records`,canP()?`<button class="btn btn-primary btn-small" data-act="empForm">＋ Add employer</button>`:'')}${r.map(x=>`<div class="queue-item"><div class="queue-symbol">▥</div><div class="queue-copy"><strong>${e(x.name)}</strong><span>${e(x.industry)} ${x.contact_name?'· '+e(x.contact_name):''} ${x.contact_email?'· '+e(x.contact_email):''} · ${x.vacancies} open vacancies · ${x.referrals} referrals · ${x.hires} hires</span></div>${badge(x.relationship)}${canP()?`<button class="text-link" data-act="empForm" data-id="${x.id}">Edit</button>`:''}</div>`).join('')||empty('No employers yet.')}</div>`};
acts.empForm=d=>{const x=d.id?cache.emps.find(y=>y.id==d.id):{};mform(d.id?'Edit employer':'Add employer','emp',d.id||'',`<div class="form-grid">${fld('Name','name',{req:1,value:x.name})}${fld('Industry','industry',{value:x.industry})}${fld('Contact person','contact_name',{value:x.contact_name})}${fld('Contact email','contact_email',{type:'email',value:x.contact_email})}${fld('Contact phone','contact_phone',{value:x.contact_phone})}${fld('Relationship','relationship',{options:['Prospect','Partner'],value:x.relationship})}${fld('Notes','notes',{area:1,full:1,value:x.notes})}</div>`,'Save')};
forms.emp=async(d,f)=>{if(f.dataset.id)await api('/api/employers/'+f.dataset.id,{method:'PATCH',body:d});else await post('/api/employers',d);closeModal();rr()};
T.outcomes=['Outcomes & retention','Follow participants after they secure employment.'];
P.outcomes=async()=>{const r=await api('/api/outcomes');cache.outs=r;const due=(o,n)=>o.start_date&&new Date(o.start_date).getTime()+n*864e5<=Date.now();const cell=(o,k,n)=>o[k]?badge(o[k]):due(o,n)?`<button class="btn btn-light btn-small" data-act="follow" data-id="${o.id}" data-k="${k}">Record</button>`:'<span class="mini">Not due</span>';return`<div class="card table-card">${head('Employment outcomes',`${r.length} records`,canP()?`<button class="btn btn-primary btn-small" data-act="newOutcome">＋ Record employment</button>`:'')}${r.length?`<table class="data-table"><thead><tr><th>Participant</th><th>Role</th><th>Type</th><th>Start</th><th>30 days</th><th>90 days</th><th>180 days</th></tr></thead><tbody>${r.map(o=>`<tr><td><a class="text-link" href="#/p/${o.participant_id}">${e(o.name)}</a></td><td>${e(o.job_title)}<small style="display:block">${e(o.employer)}</small></td><td>${e(o.employment_type)}</td><td>${e(o.start_date)}</td><td>${cell(o,'d30',30)}</td><td>${cell(o,'d90',90)}</td><td>${cell(o,'d180',180)}</td></tr>`).join('')}</tbody></table>`:empty('No employment outcomes recorded yet.')}</div>`};
acts.follow=d=>mform('Retention follow-up','follow',d.id+'|'+d.k,fld('Result','v',{req:1,options:['Still employed','Changed employer','Left employment','Could not reach']}),'Save');
forms.follow=async(d,f)=>{const [id,k]=f.dataset.id.split('|');await api('/api/outcomes/'+id,{method:'PATCH',body:{[k]:d.v}});closeModal();rr()};
acts.newOutcome=async()=>{const p=await api('/api/participants?view=participants');mform('Record employment','out','',`<div class="form-grid">${fld('Participant','participant_id',{req:1,options:p.map(x=>[x.id,x.name])})}${fld('Employer','employer',{req:1})}${fld('Job title','job_title',{req:1})}${fld('Employment type','employment_type',{options:['Full-time','Part-time','Contract','Seasonal']})}${fld('Start date','start_date',{req:1,type:'date'})}</div>`,'Save')};
forms.out=async d=>{await post('/api/outcomes',d);closeModal();rr()};
T.communications=['Communications centre','Editable templates and a full message history.'];
P.communications=async()=>{const [t,m]=await Promise.all([api('/api/templates'),api('/api/messages')]);cache.tpls=t.rows;return`${t.email?'':`<div class="warn">${window.AmalEngine?'GitHub Pages cannot send email by itself. Messages reach the portal, and "Open in email" sends one from your own mail app.':'No email service is connected, so messages reach participants in their portal but not by email. Add SMTP settings on the server to send email.'}</div>`}<div class="two-col"><div class="card">${head('Email templates','Sent automatically at each workflow step')}${t.rows.map(x=>`<div class="queue-item"><div class="queue-copy"><strong>${e(x.label)}</strong><span>${e(x.subject)}</span></div>${badge(x.auto?'Active':'Off')}${canC()?`<button class="text-link" data-act="editT" data-k="${x.key}">Edit</button>`:''}</div>`).join('')}</div><div class="card">${head('Message history')}${m.map(x=>`<div class="req"><div class="req-top"><b>${e(x.direction==='in'?'From ':'To ')}${e(x.name||x.to_email)}: ${e(x.subject)}</b>${badge(x.status||'')}</div><small>${dtt(x.at)}${x.error&&!window.AmalEngine?' · '+e(x.error):''}</small>${window.AmalEngine&&x.to_email&&x.direction!=='in'?`<a class="text-link" href="mailto:${e(x.to_email)}?subject=${encodeURIComponent(x.subject)}&body=${encodeURIComponent(x.body)}">Open in email</a>`:''}</div>`).join('')||empty('No messages yet.')}</div></div>`};
acts.editT=d=>{const x=cache.tpls.find(t=>t.key===d.k);mform('Edit template','tplE',d.k,`${fld('Subject','subject',{req:1,value:x.subject})}${fld('Body','body',{req:1,area:1,h:200,value:x.body})}${fld('Send automatically','auto',{options:[['1','Yes'],['0','No']],value:x.auto})}`,'Save')};
forms.tplE=async(d,f)=>{await api('/api/templates/'+f.dataset.id,{method:'PUT',body:{...d,auto:d.auto==='1'}});closeModal();rr()};
T.reports=['Reports & analytics','Programme performance from live records.'];
P.reports=async()=>{const r=await api('/api/reports');return`<div class="two-col"><div class="card">${head('Conversion between stages')}${r.conversion.map(c=>`<div class="bar-row" style="grid-template-columns:230px 1fr 42px"><span>${e(c.from)} → ${e(c.to)} <span class="mini">(${c.to_n}/${c.from_n})</span></span><div class="bar-track"><div class="bar-fill" style="width:${c.rate||0}%"></div></div><strong>${c.rate==null?'—':c.rate+'%'}</strong></div>`).join('')}</div><div class="card">${head('Training completion')}${r.training.map(t=>`<div class="queue-item"><div class="queue-copy"><strong>${e(t.title)}</strong><span>${t.verified||0} verified of ${t.assigned} assigned · ${t.overdue||0} overdue</span></div></div>`).join('')}</div><div class="card">${head('Retention')}<dl class="kv"><dt>Employment starts</dt><dd>${r.retention.employed}</dd><dt>Still employed at 30 days</dt><dd>${r.retention.d30}</dd><dt>Still employed at 90 days</dt><dd>${r.retention.d90}</dd><dt>Still employed at 180 days</dt><dd>${r.retention.d180}</dd></dl></div><div class="card">${head('Vacancies by source')}${r.bySource.map(s=>`<div class="queue-item"><div class="queue-copy"><strong>${e(s.source)}</strong><span>${s.open} open of ${s.n}</span></div></div>`).join('')||empty('No vacancies yet.')}</div><div class="card">${head('Referrals by status')}${r.referrals.map(s=>`<div class="queue-item"><div class="queue-copy"><strong>${e(s.status)}</strong></div><div class="queue-number">${s.n}</div></div>`).join('')||empty('No referrals yet.')}</div><div class="card">${head('Exports','CSV files, logged in the audit trail')}${['participants','vacancies','referrals','employers','outcomes'].concat(canA()?['audit']:[]).map(k=>`<div class="queue-item"><div class="queue-copy"><strong>${k[0].toUpperCase()+k.slice(1)}</strong></div><button class="text-link" data-act="csv" data-k="${k}">Download ↓</button></div>`).join('')}</div></div>`};
const ROLE_L=[['super_admin','Super Administrator'],['programme_manager','Programme Manager'],['employment_advisor','Employment Advisor'],['training_coordinator','Training Coordinator'],['read_only','Read-only Management']];
T.settings=['Settings & roles','Staff access, matching rules and governance.'];
P.settings=async()=>{const s=await api('/api/settings'),[u,au]=canA()?await Promise.all([api('/api/users'),api('/api/audit')]):[[],[]];const W=[['education','Education and qualifications'],['skills','Technical and professional skills'],['experience','Work experience'],['certifications','Certifications and licences'],['other','Additional job-specific requirements']];return`<div class="two-col">${canA()?`<div class="card">${head('Staff and roles','One person can hold several roles',`<button class="btn btn-primary btn-small" data-act="newUser">＋ Add staff</button>`)}${u.map(x=>`<div class="queue-item"><div class="queue-copy"><strong>${e(x.name)}</strong><span>${e(x.email)} · ${e(x.roles.map(r=>r.replace(/_/g,' ')).join(', '))}${x.pending?' · invitation pending':''}</span></div>${badge(x.active?'Active':'Deactivated')}${x.id!==me.id?`<button class="text-link" data-act="toggleUser" data-id="${x.id}" data-on="${x.active?0:1}">${x.active?'Deactivate':'Reactivate'}</button>`:''}</div>`).join('')}</div>`:''}<div class="card">${head('Matching weights','Must total 100. Unmet mandatory requirements always override the score.')}<form data-form="weights" class="stack">${W.map(([k,l])=>fld(l,k,{type:'number',req:1,value:s.weights[k]})).join('')}${canC()?'<button class="btn btn-primary btn-small">Save weights</button>':''}</form></div>${canA()&&window.AmalEngine?`<div class="card">${head('Workspace backup','Records live in this browser. Use this to protect them or move them to the pitching laptop.')}<div class="actions-row"><button class="btn btn-light btn-small" data-act="backup">Download backup</button><label class="btn btn-light btn-small">Restore backup<input type="file" accept=".json" style="display:none" onchange="acts.restore(this)"></label></div></div>`:''}${canA()?`<div class="card" style="grid-column:1/-1">${head('Audit log','Most recent 300 events')}<div style="max-height:360px;overflow:auto">${au.map(a=>`<div class="req"><div class="req-top"><b>${e(a.action)}</b><span class="mini">${dtt(a.at)}</span></div><small>${e(a.user_name)} · ${e(a.entity)} ${e(a.entity_id)}</small></div>`).join('')}</div></div>`:''}</div>`};
forms.weights=async d=>{await api('/api/settings/weights',{method:'PUT',body:d});toast('Weights saved. New assessments will use them.')};
acts.newUser=()=>mform('Add staff member','user','',`${fld('Full name','name',{req:1})}${fld('Email','email',{req:1,type:'email'})}<div class="form-field"><label>Roles</label>${ROLE_L.map(([k,l])=>`<label class="mini" style="display:block"><input type="checkbox" name="r_${k}"> ${l}</label>`).join('')}</div>`,'Create and invite');
forms.user=async d=>{const r=await post('/api/users',{name:d.name,email:d.email,roles:ROLE_L.map(x=>x[0]).filter(k=>d['r_'+k])});openModal('Invitation ready',`<p class="card-sub">Send this private link if the email does not arrive:</p><div class="ev" style="word-break:break-all">${e(r.inviteLink)}</div>`);};
acts.toggleUser=async d=>{await api('/api/users/'+d.id,{method:'PATCH',body:{active:d.on==='1'}});rr()};
acts.backup=async()=>{const u=URL.createObjectURL(await window.AmalEngine.backup());const a=document.createElement('a');a.href=u;a.download='amal-connect-backup.json';a.click();URL.revokeObjectURL(u)};
acts.restore=async i=>{if(!i.files[0]||!confirm('Replace everything in this browser with this backup?'))return;await window.AmalEngine.restore(i.files[0]);sessionStorage.clear();localStorage.removeItem('amal_token');location.reload()};
// ---------- Participant portal
const VP={};const PT={home:['Your employment journey','Your next step, in one place.'],application:['My application','Every stage and date.'],appointments:['My appointments','Your sessions with Amal.'],training:['My training','Assigned programmes and your Activation Session.'],documents:['My documents','Your CVs, consent and certificates.'],profile:['My employment profile','Keep your CV and preferences up to date.'],jobs:['Find jobs','Opportunities Amal has made available to you.'],applications:['My applications','Your referrals and their status.'],messages:['Messages','Communications with Amal.'],account:['My account','Security and your privacy.']};
function nextStep(d){const p=d.participant,c=d.consents.find(x=>x.status==='Issued');if(c)return['Sign your consent form','Please read it and sign it to continue.','#/me/application'];const s=d.sessions.find(x=>x.status==='Scheduled');if(s)return['Attend your information session',dtt(s.at),'#/me/appointments'];const a=d.assignments.find(x=>['Not started','In progress'].includes(x.status));if(a)return[`Complete ${a.title}`,a.deadline?'Due '+a.deadline:'Continue your assigned training.','#/me/training'];const ac=d.activations.find(x=>x.status==='Scheduled');if(ac)return['Attend your Activation Session',dtt(ac.at),'#/me/appointments'];if(!d.cv)return['Upload your CV','Amal uses it to find suitable work with you.','#/me/profile'];if(p.stage==='Employed')return['Congratulations on your new job','Amal will check in with you. Message us any time.','#/me/messages'];if(p.stage==='Employment Ready')return['Keep your profile current','You are Employment Ready. Update your CV and preferences as things change.','#/me/profile'];return['We are reviewing your progress','Your advisor will be in touch about your next step.','#/me/application']}
const pgPct=d=>{const i=STAGES.indexOf(d.participant.stage);return i<0?0:Math.round((i+1)/9*100)};
VP.home=d=>{const n=nextStep(d),req=d.assignments;return`<div class="portal-next"><div class="eyebrow">YOUR NEXT STEP</div><h2>${e(n[0])}</h2><p>${e(n[1])}</p><button class="btn btn-light btn-small" style="margin-top:12px" data-go="${n[2]}">Go →</button></div><div class="card" style="margin-top:15px">${head('Your progress')}${timeline(d.participant.stage)}</div><div class="two-col" style="margin-top:15px"><div class="card">${head('Your programme')}${req.map(a=>`<div class="queue-item"><div class="queue-copy"><strong>${e(a.title)}</strong></div>${badge(a.status)}</div>`).join('')||empty('Training will appear here once you are enrolled.')}</div><div class="card">${head('Your Amal contact')}<p class="card-sub">${e(d.advisor||'An advisor will be assigned to you soon.')}</p><button class="btn btn-light btn-small" data-go="#/me/messages">Send a message</button></div></div>`};
VP.application=d=>`<div class="card">${head('Timeline')}${d.history.map(h=>`<div class="req"><div class="req-top"><b>${e(h.stage)}</b><span class="mini">${dtt(h.at)}</span></div><small>${e(h.note||'')}</small></div>`).join('')}</div><div class="card" style="margin-top:15px">${head('Consent forms')}${d.consents.map(c=>`<div class="req"><div class="req-top"><b>${e(c.title)} v${c.version}</b>${badge(c.status)}</div>${c.status==='Issued'?`<pre class="cvtext" style="margin-top:8px">${e(c.body)}</pre><form data-form="sign" data-id="${c.id}" class="stack" style="margin-top:8px">${fld('Type your full name to sign','signed_name',{req:1})}<label class="mini"><input type="checkbox" name="agree" required> I have read this document and I agree</label><button class="btn btn-primary btn-small">Sign</button></form>`:c.signed_at?`<small>Signed ${dtt(c.signed_at)}</small><details><summary>View</summary><pre class="cvtext">${e(c.body)}</pre></details>`:''}</div>`).join('')||empty('No consent forms yet.')}</div>`;
forms.sign=async(d,f)=>{await post(`/api/portal/consents/${f.dataset.id}/sign`,{...d,agree:!!d.agree});toast('Signed. Thank you.');rr()};
VP.appointments=d=>`<div class="card">${[...d.sessions.map(s=>({...s,k:'Information session'})),...d.activations.map(s=>({...s,k:'Activation Session'}))].map(s=>`<div class="queue-item"><div class="queue-symbol">◷</div><div class="queue-copy"><strong>${s.k}</strong><span>${dtt(s.at)} · ${e(s.location)}</span></div>${badge(s.status)}</div>`).join('')||empty('No appointments yet.')}</div>`;
VP.training=d=>{const all=d.assignments.filter(a=>a.required),done=all.length&&all.every(a=>a.status==='Verified');return`${d.assignments.map(a=>`<div class="card" style="margin-bottom:12px">${head(a.title,a.description,badge(a.status))}<p class="card-sub">${a.deadline?'Deadline: '+e(a.deadline)+' · ':''}${e(a.completion||'')}</p>${a.materials.map(m=>`<button class="text-link" data-act="dl" data-id="${m.id}" data-name="${e(m.name)}">${e(m.name)} ↓</button><br>`).join('')}${['Not started','In progress'].includes(a.status)?`<form data-form="pdone" data-id="${a.id}" class="toolbar-left" style="margin-top:8px"><input type="file" name="evidence"><input class="field" name="note" placeholder="Note for your advisor"><button class="btn btn-primary btn-small">Mark as completed</button></form>`:a.status==='Completed'?'<p class="mini">Waiting for Amal to verify.</p>':''}</div>`).join('')||`<div class="card">${empty('Training will appear here once you are enrolled.')}</div>`}<div class="card">${head('Activation Session','Mandatory milestone',badge(done?'Unlocked':'Locked'))}<p class="card-sub">${done?'Amal will schedule your session with you.':'Unlocks when your required training has been verified.'}</p></div>`};
forms.pdone=async(d,f,fd)=>{if(!fd.get('evidence')?.size)fd.delete('evidence');await api(`/api/portal/assignments/${f.dataset.id}/complete`,{form:fd});toast('Sent for verification');rr()};
VP.documents=d=>`<div class="card">${d.documents.map(x=>`<div class="queue-item"><div class="queue-copy"><strong>${e(x.name)}</strong><span>${e(x.kind)} · ${dt(x.at)}</span></div><button class="text-link" data-act="dl" data-id="${x.id}" data-name="${e(x.name)}">Download</button></div>`).join('')||empty('No documents yet.')}</div>`;
VP.profile=d=>{const pr=d.participant.preferences,c=d.cv;return`<div class="two-col"><div class="stack"><div class="card">${head('Your CV',c?`Version ${c.version} · ${dt(c.at)}`:'PDF, Word or a clear photo')}<form data-form="mycv"><div class="drop"><input type="file" name="cv" required accept="${CV_ACCEPT}"></div><button class="btn btn-primary btn-small" style="margin-top:8px">Upload</button></form></div>${c?`<div class="card">${head('What we read from your CV','Correct anything that is wrong')}${profileView({profile:c.profile})}<form data-form="mycvfix" class="stack" style="margin-top:10px">${fld('Skills (comma separated)','skills',{area:1,value:(c.profile.skills||[]).join(', ')})}${fld('Certifications (comma separated)','certifications',{area:1,value:(c.profile.certifications||[]).join(', ')})}${fld('Languages (comma separated)','languages',{value:(c.profile.languages||[]).join(', ')})}<button class="btn btn-light btn-small">Save corrections</button></form></div>`:''}</div><div class="card">${head('Job preferences','These guide recommendations but never replace job requirements')}<form data-form="prefs" class="stack">${fld('Preferred occupations','occupations',{value:pr.occupations})}${fld('Preferred industries','industries',{value:pr.industries})}${fld('Preferred locations in NL','locations',{value:pr.locations})}${fld('Work arrangement','workArrangement',{value:pr.workArrangement,options:['No preference','On-site only','Remote only','Hybrid']})}${fld('Employment type','employmentType',{value:pr.employmentType,options:['No preference','Full-time only','Part-time only']})}${fld('Availability','availability',{value:d.participant.availability,options:['Available for opportunities','Currently interviewing or awaiting outcomes','Temporarily unavailable']})}${fld('Phone','phone',{value:d.participant.phone})}${fld('City','city',{value:d.participant.city})}<button class="btn btn-primary btn-small">Save</button></form></div></div>`};
forms.mycv=async(d,f,fd)=>{const r=await api('/api/portal/cv',{form:fd});toast(`Your CV was read (version ${r.version})`);rr()};
forms.mycvfix=async d=>{const s=v=>v.split(',').map(x=>x.trim()).filter(Boolean);await api('/api/portal/profile',{method:'PATCH',body:{cvProfile:{skills:s(d.skills),certifications:s(d.certifications),languages:s(d.languages)}}});toast('Corrections saved');rr()};
forms.prefs=async d=>{const {availability,phone,city,...preferences}=d;await api('/api/portal/profile',{method:'PATCH',body:{availability,phone,city,preferences}});toast('Saved')};
VP.jobs=d=>d.participant.stage!=='Employment Ready'&&d.participant.stage!=='Employed'?`<div class="card">${empty('Jobs appear here once you are Employment Ready and Amal has reviewed an opportunity for you.')}</div>`:(d.jobs.map(j=>`<div class="job-card"><div class="job-top"><div><h3>${e(j.title)}</h3><p>${e(j.employer)} · ${e(j.location)}</p></div>${badge(j.referral_status)}</div><div class="job-meta"><span>${e(j.type||'')}</span>${j.closing?`<span>Closes ${dt(j.closing)}</span>`:''}</div>${j.suitability?`<p class="card-sub">${e(j.suitability.explanation)}</p>`:''}${j.decision_note?`<div class="ev">${e(j.decision_note)}</div>`:''}${j.url?`<a class="text-link" target="_blank" rel="noopener" href="${e(j.url)}">View and apply ↗</a>`:''}</div>`).join('')||`<div class="card">${empty('Amal has not released a job to you yet. We will notify you when one is approved.')}</div>`);
VP.applications=d=>`<div class="card">${d.applications.map(a=>`<div class="queue-item"><div class="queue-copy"><strong>${e(a.job_title)}</strong><span>${e(a.employer)} · ${dt(a.created)}</span></div>${badge(a.status)}</div>`).join('')||empty('No applications yet.')}</div>`;
VP.messages=d=>`<div class="card">${head('Message Amal')}<form data-form="pmsg" class="stack">${fld('Subject','subject',{req:1})}${fld('Message','body',{req:1,area:1})}<button class="btn btn-primary btn-small">Send</button></form></div><div class="card" style="margin-top:15px">${d.messages.map(m=>`<div class="req"><div class="req-top"><b>${m.direction==='in'?'You: ':''}${e(m.subject)}</b><span class="mini">${dtt(m.at)}</span></div><small style="white-space:pre-wrap">${e(m.body)}</small></div>`).join('')||empty('No messages yet.')}</div>`;
forms.pmsg=async d=>{await post('/api/portal/messages',d);toast('Sent');rr()};
VP.account=d=>`<div class="two-col"><div class="card">${head('Change password')}<form data-form="pw" class="stack">${fld('Current password','current',{req:1,type:'password'})}${fld('New password (10+ characters)','password',{req:1,type:'password',min:10})}<button class="btn btn-primary btn-small">Update</button></form></div><div class="card">${head('Your privacy','Your information is visible only to you and authorized Amal staff')}<button class="btn btn-light btn-small" data-act="myData">Download my data</button></div></div>`;
forms.pw=async(d,f)=>{await post('/api/password',d);f.reset();toast('Password updated')};
acts.myData=async()=>{const r=await api('/api/portal/export');const u=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='my-amal-data.json';a.click();URL.revokeObjectURL(u)};
// ---------- Router
async function route(){closeModal();const raw=location.hash.slice(1)||'/';const [pathPart,qs]=raw.split('?');const parts=pathPart.split('/').filter(Boolean);const query=Object.fromEntries(new URLSearchParams(qs||''));
 if(parts[0]==='invite')return viewInvite(parts[1]);if(parts[0]==='apply'&&!token)return viewApply();
 if(!me&&token){try{me=await api('/api/me',{quiet:true})}catch{token='';sessionStorage.removeItem('amal_token');localStorage.removeItem('amal_token')}}
 if(!me){let st;try{st=await api('/api/status')}catch(x){return authPage(`<h1>Server not connected</h1><p>${e(x.message)}</p><p>Please reload this page.</p>`)}return st.needsSetup?viewSetup():viewLogin()}
 if(!me.staff){const page=parts[0]==='me'&&PT[parts[1]]?parts[1]:'home';shell(PNAV,'#/me/',page,PT[page][0],PT[page][1],'<div class="empty"><span class="spinner"></span>Loading…</div>');try{const d=await api('/api/portal');$('#pageContent').innerHTML=VP[page](d)}catch(x){$('#pageContent').innerHTML=`<div class="err">${e(x.message)}</div>`}return}
 const page=P[parts[0]]?parts[0]:'overview';const nk=page==='p'?'participants':page;shell(NAV,'#/',nk,T[page][0],T[page][1],'<div class="empty"><span class="spinner"></span>Loading…</div>',['overview','applicants','participants'].includes(page)&&canP()?newBtn(true):'');try{$('#pageContent').innerHTML=await P[page](query,parts[1])}catch(x){$('#pageContent').innerHTML=`<div class="err">${e(x.message)}</div>`}}
window.addEventListener('hashchange',route);(window.AmalEngineReady||Promise.resolve()).then(route).catch(x=>authPage(`<h1>Could not start</h1><p>${e(x.message)}</p>`));
